Object.assign(window.TEM8_DICTIONARY, {"attack":{"media":{"uk":"media/uk/attack__gb_1.mp3","us":"media/us/attack__us_1.mp3"},"oxford":{"phon":"əˈtæk","pos":"noun","senses":[{"en":"an act of using violence to try to hurt or kill somebody","cn":"袭击；攻击","g":"[countable, uncountable]","sc":"violence","ex":{"en":"Five people were killed in the attacks that took place last night.","cn":"在昨晚发生的袭击中有五人遇害。"}},{"en":"an act of trying to kill or injure the enemy in war, using weapons such as guns and bombs","cn":"（在战争中使用武器的）进攻，攻击","g":"[countable, uncountable]","sc":"in war","ex":{"en":"a bomb/rocket/missile attack","cn":"炸弹／火箭／导弹攻击"}},{"en":"a sudden, short period of illness, usually severe","cn":"（疾病的）发作，侵袭","g":"[countable]","sc":"of illness","ex":{"en":"to suffer an asthma attack","cn":"哮喘发作"}},{"en":"a sudden period of feeling an emotion such as fear","cn":"（情感的）一阵突发","g":"[countable]","lab":"figurative","sc":"of emotion","ex":{"en":"a panic attack","cn":"惊恐发作"}},{"en":"strong criticism of somebody/something in speech or in writing","cn":"（口头或书面的）抨击，非难","g":"[countable, uncountable]","sc":"criticism","ex":{"en":"He found himself the victim of an unprovoked attack by the media.","cn":"他发现自己成为媒体无端攻击的受害者。"}},{"en":"the players in a team whose job is to try to score goals or points","cn":"进攻队员","g":"[singular]","lab":"British English","sc":"in sport","ex":{"en":"Germany's attack has been weakened by the loss of some key players through injury.","cn":"德国队几名主力队员因伤不能上场，削弱了进攻力量。"}},{"en":"the actions that players take to try to score a goal or win the game","cn":"（队员等的）进攻","g":"[countable, uncountable]","sc":"in sport","ex":{"en":"a sustained attack on the Arsenal goal","cn":"向阿森纳队球门的持续进攻"}},{"en":"an action that you take to try to stop or change something that you feel is bad","cn":"抑制；打击；处理","g":"[countable]","sc":"action to stop something","ex":{"en":"to launch an all-out attack on poverty/unemployment","cn":"全力抑制贫穷／失业"}},{"en":"the action of something such as an insect, or a disease, that causes damage to something/somebody","cn":"（病虫等的）损害，伤害","g":"[uncountable, countable]","sc":"damage","ex":{"en":"The roof timbers were affected by rot and insect attack.","cn":"屋顶的木料已经腐朽并遭虫蛀。"}},{"en":"to use violence to try to hurt or kill somebody","cn":"袭击；攻击","g":"[intransitive, transitive]","sc":"use violence","ex":{"en":"Most dogs will not attack unless provoked.","cn":"大多数的狗受到挑衅才会攻击。"},"pos":"verb"},{"en":"to use weapons, such as guns and bombs against an enemy in a war, etc.","cn":"（在战争等中使用武器）进攻，攻击","g":"[intransitive, transitive]","sc":"in war","ex":{"en":"Enemy forces attacked at night.","cn":"敌军在夜间进攻。"},"pos":"verb"},{"en":"to criticize somebody/something severely","cn":"抨击；非难","g":"[transitive]","sc":"criticize","ex":{"en":"His latest work has been bitterly attacked by the critics.","cn":"他的最新作品受到评论家的猛烈抨击。"},"pos":"verb"},{"en":"to have a harmful effect on something","cn":"侵袭；损害","g":"[transitive]","sc":"damage","ex":{"en":"a disease that attacks the brain","cn":"侵袭大脑的疾病"},"pos":"verb"},{"en":"to go forward in a game in order to try to score goals or points","cn":"进攻","g":"[intransitive]","sc":"in sport","ex":{"en":"Spain attacked more in the second half and deserved a goal.","cn":"西班牙队在下半场加强攻势，攻进了一球。"},"pos":"verb"},{"en":"to deal with something with a lot of energy","cn":"奋力处理；全力对付","g":"[transitive]","sc":"do something with energy","ex":{"en":"Let's attack one problem at a time.","cn":"咱们每次全力处理一个问题。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"攻击；进攻","en":"To attack a person or place means to try to hurt or damage them using physical violence.","ex":{"en":"Fifty civilians in Masawa were killed when government planes attacked the town","cn":"马萨瓦市遭到政府军飞机轰炸，有50名平民丧生。"}},{"pos":"VERB 动词","cn":"抨击;强烈指责;非难","en":"If you attack a person, belief, idea, or act, you criticize them strongly.","ex":{"en":"He publicly attacked the people who've been calling for secret ballot nominations","cn":"他公开抨击了那些主张用不记名投票方式确定任命人选的人。"}},{"pos":"VERB 动词","cn":"（疾病、化学药品、昆虫等）攻击，侵蚀，破坏","en":"If something such as a disease, a chemical, or an insect attacks something, it harms or spoils it.","ex":{"en":"The virus seems to have attacked his throat","cn":"病毒看来已经侵蚀到他喉部了。"}},{"pos":"VERB 动词","cn":"（积极地）解决（问题），开展（工作）","en":"If you attack a job or a problem, you start to deal with it in an energetic way.","ex":{"en":"Any attempt to attack the budget problem is going to have to in some way deal with those issues.","cn":"要解决预算问题，在某种程度上就必须解决那些问题。"}},{"pos":"VERB 动词","cn":"（在足球等比赛中）进攻","en":"In games such as football, when one team attacks the opponent's goal, they try to score a goal.","ex":{"en":"Now the US is controlling the ball and attacking the opponent's goal","cn":"现在美国队控球，向对方球门展开了进攻。"}},{"pos":"N-COUNT 可数名词","cn":"（疾病短时间的）侵袭，发作","en":"An attack of an illness is a short period in which you suffer badly from it.","ex":{"en":"It had brought on an attack of asthma.","cn":"这引发了哮喘。"}}]},"examples":[{"en":"Germany's attack has been weakened by the loss of some key players through injury.","cn":"德国队几名主力队员因伤不能上场，削弱了进攻力量。"},{"en":"The school has come under attack for failing to encourage bright pupils.","cn":"这所学校因未能鼓励聪明学生而受到非难。"}]},"at":{"media":{"uk":"media/uk/at__gb_1.mp3","us":"media/us/at__us_1.mp3"},"oxford":{"phon":"ət","pos":"preposition","senses":[{"en":"used to say where something/somebody is or where something happens","cn":"在（某处）","ex":{"en":"at the corner of the street","cn":"在街角"}},{"en":"used to say where somebody works or studies","cn":"在（表示学习或工作地点）","ex":{"en":"He's been at the bank longer than anyone else.","cn":"他在银行工作的时间比任何人都长。"}},{"en":"used to say when something happens","cn":"在（某时间或时刻）","lab":"British English","ex":{"en":"We left at 2 o'clock.","cn":"我们在两点钟离开的。"}},{"en":"used to state the age at which somebody does something","cn":"在…岁时","ex":{"en":"She got married at 25.","cn":"她 25 岁结婚。"}},{"en":"in the direction of or towards somebody/something","cn":"向；朝","ex":{"en":"What are you looking at?","cn":"你在看什么？"}},{"en":"used after a verb to show that somebody tries to do something, or partly does something, but does not succeed or complete it","cn":"（用于动词后，涉及未做成或未做完的事）","ex":{"en":"He clutched wildly at the rope as he fell.","cn":"他坠落时拼命想抓住绳子。"}},{"en":"used with adjectives to show how well somebody does something","cn":"（与形容词连用，表示能力）在…方面","ex":{"en":"I'm good at French.","cn":"我的法语很好。"}},{"en":"used to show a rate, speed, etc.","cn":"（用于速度、比率等）以，达","ex":{"en":"He was driving at 70 mph.","cn":"他以每小时 70 英里的速度驾车行驶。"}},{"en":"used to state the distance away from something","cn":"在…远；从相隔…远的地方","ex":{"en":"I held it at arm's length.","cn":"我伸直胳膊提着它。"}},{"en":"used to show the situation somebody/something is in, what somebody is doing or what is happening","cn":"处于…状态","ex":{"en":"The country is now at war.","cn":"这个国家正在打仗。"}},{"en":"used to say that somebody/something is as good, bad, etc. as they can be","cn":"处于最佳（或最差等）状态；在全盛（或谷底等）时期","ex":{"en":"This was Osaka at her best.","cn":"这是大阪最美的时节。"}},{"en":"used with adjectives to show the cause of something","cn":"（与形容词连用）因为，由于，对…","ex":{"en":"They were impatient at the delay.","cn":"他们对拖延不耐烦了。"}},{"en":"in response to something","cn":"应…（而）；响应；回答","lab":"formal","ex":{"en":"They attended the dinner at the chairman's invitation.","cn":"他们应董事长之邀出席了宴会。"}},{"en":"used when giving a phone number","cn":"（提供电话号码时用）","lab":"North American English","ex":{"en":"You can reach me at 637-2335, extension 354.","cn":"你可以打 637-2335 这个电话号码，转分机 354 与我联系。"}},{"en":"the symbol (@) used in email addresses","cn":"（用于电子邮箱地址中的符号 @）","lab":"computing"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在（某地）；在（某场合）","en":"You use at to indicate the place or event where something happens or is situated.","ex":{"en":"We had dinner at a restaurant in Attleborough","cn":"我们在阿特尔伯勒的一家餐厅里吃的饭。"}},{"pos":"PREP 介词","cn":"在（上学）","en":"If someone is at school or college, or at a particular school or college, they go there regularly to study.","ex":{"en":"He was shy and nervous as a boy, and unhappy at school","cn":"他小时候既害羞又胆怯，在学校过得并不快乐。"}},{"pos":"PREP 介词","cn":"在…旁边；靠近","en":"If you are at something such as a table, a door, or someone's side, you are next to it or them.","ex":{"en":"An assistant sat typing away at a table beside him","cn":"助手坐在他身旁的一张桌子上埋头打字。"}},{"pos":"PREP 介词","cn":"从相隔（一段距离）的地方;呈…角度","en":"When you are describing where someone or something is, you can say that they are at a certain distance. You can also say that one thing is at an angle in relation to another thing.","ex":{"en":"The two journalists followed at a discreet distance","cn":"那两个记者谨慎地保持距离跟在后面。"}},{"pos":"PREP 介词","cn":"在（某时间或时刻）","en":"If something happens at a particular time, that is the time when it happens or begins to happen.","ex":{"en":"The funeral will be carried out this afternoon at 3.00","cn":"葬礼将在今天下午3点举行。"}},{"pos":"PREP 介词","cn":"在（某一年龄时）；在…岁时","en":"If you do something at a particular age, you do it when you are that age.","ex":{"en":"Blake emigrated to Australia with his family at 13","cn":"布莱克在13岁时随家人移民到了澳大利亚。"}},{"pos":"PREP 介词","cn":"以，达（某一速度、频率、水平或价格）","en":"You use at to express a rate, frequency, level, or price.","ex":{"en":"I drove back down the highway at normal speed","cn":"我以正常车速沿公路返回。"}},{"pos":"PREP 介词","cn":"以，达（某一数量）","en":"You use at before a number or amount to indicate a measurement.","ex":{"en":"Weighing in at eighty tons, the B-19 was easily the largest and most sophisticated warplane in the world.","cn":"B-19重达80吨，无疑是世界上最大、最先进的军用飞机。"}},{"pos":"PREP 介词","cn":"朝（某人或某物看）；向（某人掷物）；冲（某人说话）","en":"If you look at someone or something, you look towards them. If you direct an object or a comment at someone, you direct it towards them.","ex":{"en":"He looked at Michael and laughed","cn":"他看着迈克尔笑了。"}},{"pos":"PREP 介词","cn":"向，朝（某人微笑、招手等）","en":"You can use at after verbs such as 'smile' or 'wave' and before nouns referring to people to indicate that you have put on an expression or made a gesture which someone is meant to see or understand.","ex":{"en":"She opened the door and stood there, frowning at me","cn":"她打开门站在那里，朝我皱着眉头。"}},{"pos":"PREP 介词","cn":"（指）向…","en":"If you point or gesture at something, you move your arm or head in its direction so that it will be noticed by someone you are with.","ex":{"en":"He pointed at the empty bottle and the waitress quickly replaced it","cn":"他指了指空瓶子，女服务员立即重新拿了一瓶。"}},{"pos":"PREP 介词","cn":"致力于;定位于;期望达到","en":"If you are working at something, you are dealing with it. If you are aiming at something, you are trying to achieve it.","ex":{"en":"She has worked hard at her marriage.","cn":"她努力维系着她的婚姻。"}},{"pos":"PREP 介词","cn":"应（某人邀请或要求）","en":"If something is done at someone's invitation or request, it is done as a result of it.","ex":{"en":"She left the light on in the bathroom at his request","cn":"她按照他的要求将浴室里的灯开着。"}},{"pos":"PREP 介词","cn":"处在…状态","en":"You use at to say that someone or something is in a particular state or condition.","ex":{"en":"I am afraid we are not at liberty to disclose that information","cn":"恐怕我们无权透露这一信息。"}},{"pos":"PREP 介词","cn":"（用于所有格代词和形容词最高级前，表示某人或某物在此时的某一特征最鲜明）","en":"You use at before a possessive pronoun and a superlative adjective to say that someone or something has more of a particular quality than at any other time.","ex":{"en":"He was at his happiest whilst playing cricket","cn":"玩板球时他最开心了。"}},{"pos":"PREP 介词","cn":"以…方式","en":"You use at to say how something is being done.","ex":{"en":"Three people were killed by shots fired at random from a minibus","cn":"3个人被从一辆面包车中发射的乱弹打死了。"}},{"pos":"PREP 介词","cn":"（表示某人重复做某事）","en":"You use at to show that someone is doing something repeatedly.","ex":{"en":"She lowered the handkerchief which she had kept dabbing at her eyes","cn":"她放下了那块一直用来擦眼睛的手帕。"}},{"pos":"PREP 介词","cn":"在…方面（擅长）","en":"You use at to indicate an activity or task when saying how well someone does it.","ex":{"en":"I'm good at my work","cn":"我对自己的工作得心应手。"}},{"pos":"PREP 介词","cn":"对…的反应","en":"You use at to indicate what someone is reacting to.","ex":{"en":"Eleanor was annoyed at having had to wait so long for him","cn":"埃莉诺为不得不等他这么长时间而感到很恼火。"}},{"pos":"","cn":"","en":"at all→see: ;"}]},"examples":[{"en":"You can reach me at 637-2335, extension 354.","cn":"你可以打 637-2335 这个电话号码，转分机 354 与我联系。"},{"en":"He managed to buy a car after all — and a nice one at that.","cn":"他终于设法买了一辆小轿车，而且还挺不错的。"}]},"attached":{"oxford":{"phon":"əˈtætʃt","pos":"adjective","senses":[{"en":"joined to something","cn":"所附的","ex":{"en":"Please complete the attached application form.","cn":"请填写所附申请表。"}},{"en":"liking somebody/something very much","cn":"热爱；钟爱","ex":{"en":"I've never seen two people so attached to each other.","cn":"我从未见过两个人如此形影不离。"}},{"en":"married or having a romantic relationship with somebody; not single","cn":"已婚的;非单身的","g":"[not usually before noun]","ex":{"en":"It would be nice to meet some more guys who aren't attached.","cn":"很高兴认识更多一些单身的人。"}},{"en":"working for or forming part of an organization","cn":"附属于；为…工作","g":"[not before noun]","ex":{"en":"The research unit is attached to the university.","cn":"这个研究单位附属于大学。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常喜欢…的，热爱…的","en":"If you are attached to someone or something, you like them very much.","ex":{"en":"She is very attached to her family and friends.","cn":"她非常热爱家人和朋友。"}},{"pos":"ADJ 形容词","cn":"（通常只是短时间）从属于…的，为…工作的","en":"If someone is attached to an organization or group of people, they are working with them, often only for a short time.","ex":{"en":"Ford was attached to the battalion's first line of transport.","cn":"福特曾在该营的第一运输队服役。"}},{"pos":"ADJ 形容词","cn":"隶属于…的;附属的","en":"If one organization or institution is attached to a larger organization, it is part of that organization and is controlled and run by it.","ex":{"en":"At one time the schools were mainly attached to the church.","cn":"这些学校曾一度归教会主管。"}}]},"media":{"uk":"media/uk/attached__gb_1.mp3","us":"media/us/attached__us_1.mp3"},"examples":[{"en":"I've never seen two people so attached to each other.","cn":"我从未见过两个人如此形影不离。"},{"en":"We've grown very attached to this house.","cn":"我们变得非常喜欢这座房子。"}]},"at-home":{"oxford":{"phon":"æt ˈhəʊm","pos":"adjective","senses":[{"en":"done or taking place at home","cn":"在家里进行（或发生）的","ex":{"en":"an at-home job","cn":"一份在家里做的工作"}},{"en":"staying at home rather than going out to work","cn":"在家的；不外出工作的","ex":{"en":"at-home dads","cn":"全职爸爸"}},{"en":"a party in somebody’s home","cn":"家中聚会","ex":{"en":"We're having an at-home—can you come?","cn":"我们要在家中聚会，你能来吗？"},"pos":"noun"}]},"media":{"uk":"media/uk/at_home_1_gb_1.mp3","us":"media/us/at_home_1_us_1.mp3"},"examples":[{"en":"We're having an at-home — can you come?","cn":"我们要在家中聚会 — 你能来吗？"},{"en":"an at-home job","cn":"一份在家里做的工作"}]},"attainment":{"media":{"uk":"media/uk/attainment__gb_1.mp3","us":"media/us/attainment__us_1.mp3"},"oxford":{"phon":"əˈteɪnmənt","pos":"noun","senses":[{"en":"something that you achieved","cn":"成就；造诣","g":"[countable, usually plural]","lab":"British English","ex":{"en":"a young woman of impressive educational attainments","cn":"一位学业成就斐然的年轻女子"}},{"en":"success in achieving something","cn":"达到；获得","g":"[uncountable]","ex":{"en":"The attainment of his ambitions was still a dream.","cn":"他要实现的抱负仍然是一个梦想。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"达到；获得","en":"The attainment of an aim is the achieving of it.","ex":{"en":"...the attainment of independence.","cn":"实现独立"}},{"pos":"N-COUNT 可数名词","cn":"成就；造诣；才能","en":"An attainment is a skill you have learned or something you have achieved.","ex":{"en":"...their educational attainments.","cn":"他们的学业成就"}}]},"examples":[{"en":"The attainment of his ambitions was still a dream.","cn":"他要实现的抱负仍然是一个梦想。"},{"en":"a young woman of impressive educational attainments","cn":"一位学业成就斐然的年轻女子"}]},"attributes":{"oxford":{"phon":"əˈtrɪbjuːt","pos":"verb","senses":[{"en":"to say or believe that sth is the result of a particular thing","cn":"把 … 归因于；认为 … 是由于"},{"en":"to say or believe that sb is responsible for doing sth, especially for saying, writing or painting sth","cn":"认为是 … 所为（或说、写、作）"}]},"media":{"uk":"media/uk/attribute__gb_1.mp3","us":"media/us/attribute__us_1.mp3"}},"attendant":{"media":{"uk":"media/uk/attendant__gb_1.mp3","us":"media/us/attendant__us_1.mp3"},"oxford":{"phon":"əˈtendənt","pos":"noun","senses":[{"en":"a person whose job is to serve or help people in a public place","cn":"服务员；侍者","ex":{"en":"a cloakroom/parking/museum attendant","cn":"衣帽间／停车服务员；博物馆接待员"}},{"en":"a person who takes care of and lives or travels with a person who has an important job, or who has a medical condition or disability","cn":"（要人的）侍从，随从；（病人的）护理者"},{"en":"closely connected with something that has just been mentioned","cn":"伴随的；随之而来的","ex":{"en":"attendant problems/risks/circumstances","cn":"随之而来的问题／风险／情况"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（加油站、停车场、更衣室等的）服务员，侍者","en":"An attendant is someone whose job is to serve or help people in a place such as a petrol station, a car park, or a cloakroom.","ex":{"en":"Tony Williams was working as a car-park attendant in Los Angeles.","cn":"托尼·威廉斯在洛杉矶的一个停车场当服务生。"}},{"pos":"ADJ 形容词","cn":"伴随的；附带的；相关的","en":"You use attendant to describe something that results from a thing already mentioned or that is connected with it.","ex":{"en":"Mr Branson's victory, and all the attendant publicity, were well deserved.","cn":"布兰森先生的胜利，以及随之而来的关注度，都是理所应当的。"}}]},"examples":[{"en":"We had all the usual problems attendant upon starting a new business.","cn":"我们遇到了创业时通常会出现的所有问题。"},{"en":"a cloakroom/parking/museum attendant","cn":"衣帽间/停车服务员；博物馆接待员"}]},"attraction":{"media":{"uk":"media/uk/attraction__gb_1.mp3","us":"media/us/attraction__us_1.mp3"},"oxford":{"phon":"əˈtrækʃn","pos":"noun","senses":[{"en":"an interesting or lively place to go or thing to do","cn":"向往的地方；有吸引力的事","g":"[countable]","ex":{"en":"Buckingham Palace is a major tourist attraction.","cn":"白金汉宫是重要的旅游胜地。"}},{"en":"a feeling of liking somebody, especially sexually","cn":"（尤指两性间的）爱慕，吸引","g":"[singular, uncountable]","ex":{"en":"She felt an immediate attraction for him.","cn":"她立即对他产生了爱慕之情。"}},{"en":"a feature, quality or person that makes something seem interesting and fun, and worth having or doing","cn":"有吸引力的特征（或品质、人）","g":"[countable, uncountable]","ex":{"en":"I can't see the attraction of sitting on a beach all day.","cn":"我看不出整天坐在海滩上有什么乐趣。"}},{"en":"a force that pulls things towards each other","cn":"吸引（力）","g":"[uncountable]","lab":"physics","ex":{"en":"gravitational/magnetic attraction","cn":"地心引力；磁力"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"爱慕;喜欢;性吸引","en":"Attraction is a feeling of liking someone, and often of being sexually interested in them.","ex":{"en":"Our level of attraction to the opposite sex has more to do with our inner confidence than how we look","cn":"我们对异性的吸引程度更多的来自内在的自信，而不是长相。"}},{"pos":"N-COUNT 可数名词","cn":"吸引力；诱惑力","en":"An attraction is a feature which makes something interesting or desirable.","ex":{"en":"...the attractions of living on the waterfront.","cn":"令人神往的滨水生活"}},{"pos":"N-COUNT 可数名词","cn":"有吸引力的地方（或事物）","en":"An attraction is something that people can go to for interest or enjoyment, for example a famous building.","ex":{"en":"The walled city is an important tourist attraction.","cn":"这座由城墙围绕的城市是个重要的旅游胜地。"}}]},"examples":[{"en":"I can't see the attraction of sitting on a beach all day.","cn":"我看不出整天坐在海滩上有什么乐趣。"},{"en":"Sexual attraction is a large part of falling in love.","cn":"堕入爱河很大部分是由于性吸引。"}]},"attention":{"media":{"uk":"media/uk/attention__gb_1.mp3","us":"media/us/attention__us_1.mp3"},"oxford":{"phon":"əˈtenʃn","pos":"noun","senses":[{"en":"the act of listening to, looking at or thinking about something/somebody carefully; interest that people show in somebody/something","cn":"注意；专心；留心；注意力","g":"[uncountable]","lab":"formal","sc":"listening/looking carefully","ex":{"en":"the report’s attention to detail","cn":"报告对细节的注意"}},{"en":"special care, action or treatment","cn":"特别照料（或行动、处理）","g":"[uncountable]","sc":"treatment/actions","ex":{"en":"He received urgent medical attention.","cn":"他得到了紧急医疗救治。"}},{"en":"things that somebody does to try to please you or to show their interest in you","cn":"殷勤；关心","g":"[countable, usually plural]","sc":"treatment/actions","ex":{"en":"She tried to escape the unwanted attentions of her former boyfriend.","cn":"她尽量避开她前男友多余的殷勤。"}},{"en":"the position soldiers take when they stand very straight with their feet together and their arms at their sides","cn":"立正姿势","g":"[uncountable]","sc":"soldiers","ex":{"en":"to stand at/to attention","cn":"立正站着；立正"}},{"en":"used for asking people to listen to something that is being announced","cn":"注意","ex":{"en":"Attention, please! Passengers for flight KL412 are requested to go to gate 21 immediately.","cn":"请注意！请 KL412 航班的乘客立即到 21 号登机口登机。"},"pos":"exclamation"},{"en":"used for ordering soldiers to stand to attention","cn":"立正","pos":"exclamation"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"注意；留心；专注","en":"If you give someone or something your attention, you look at it, listen to it, or think about it carefully.","ex":{"en":"You have my undivided attention","cn":"我专心听你所讲。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指大众的）注意力，关注","en":"Attention is great interest that is shown in someone or something, particularly by the general public.","ex":{"en":"Volume Two, subtitled 'The Lawyers', will also attract considerable attention","cn":"副标题为“律师”的第二册也将获得广泛关注。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"保养;照料;照顾","en":"If someone or something is getting attention, they are being dealt with or cared for.","ex":{"en":"Each year more than two million household injuries need medical attention.","cn":"每年有超过200万起家中受伤事件需要医疗处理。"}},{"pos":"N-PLURAL 复数名词","cn":"（尤指令人讨厌的）关注，殷勤","en":"You can refer to someone's efforts to help you, or the interest they show in you, as their attentions, especially if you dislike or disapprove of them.","ex":{"en":"The only way to escape the unwanted attentions of the local men was not to go out","cn":"避免被当地人指指点点的唯一办法就是闭门不出。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"注意;注意力","en":"If you bring something to someone's attention or draw their attention to it, you tell them about it or make them notice it.","ex":{"en":"If we don't keep bringing this to the attention of the people, nothing will be done","cn":"如果我们无法让群众一直关注此事，那将一事无成。"}},{"pos":"PHRASE 短语","cn":"（突然）吸引…的注意","en":"If someone or something attracts your attention or catches your attention, you suddenly notice them.","ex":{"en":"A faint aroma of coffee attracted his attention","cn":"淡淡的咖啡香味一下子吸引了他。"}},{"pos":"PHRASE 短语","cn":"关心/不关心；注意/不注意","en":"If you pay attention to someone, you watch them, listen to them, or take notice of them. If you pay no attention to someone, you behave as if you are not aware of them or as if they are not important.","ex":{"en":"More than ever before, the food industry is paying attention to young consumers","cn":"食品工业比以往任何时候都更加关注年轻消费者。"}},{"pos":"PHRASE 短语","cn":"立正","en":"When people stand to attention or stand at attention, they stand straight with their feet together and their arms at their sides.","ex":{"en":"Soldiers in full combat gear stood at attention","cn":"全副武装的士兵们立正站着。"}}]},"examples":[{"en":"Attention, please! Passengers for flight KL412 are requested to go to gate 21 immediately.","cn":"请注意！请 KL412 航班的乘客立即到 21 号门登机。"},{"en":"( formal ) He called (their) attention to the fact that many files were missing.","cn":"他提请他们注意许多档案已经遗失这一事实。"}]},"attractive":{"media":{"uk":"media/uk/attractive__gb_1.mp3","us":"media/us/attractive__us_1.mp3"},"oxford":{"phon":"əˈtræktɪv","pos":"adjective","senses":[{"en":"pleasant to look at, especially in a sexual way","cn":"性感的；妩媚的；英俊的；诱人的","ex":{"en":"an attractive woman","cn":"妩媚的女人"}},{"en":"pleasant","cn":"吸引人的；令人愉快的","ex":{"en":"a big house with an attractive garden","cn":"带有美丽花园的一所巨宅"}},{"en":"having features or qualities that make something seem interesting and worth having","cn":"（事物）有吸引力的；诱人的","ex":{"en":"an attractive offer/proposition/option","cn":"诱人的提议／建议／选项"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）漂亮的，动人的，有魅力的","en":"A person who is attractive is pleasant to look at.","ex":{"en":"She's a very attractive woman","cn":"她是个妩媚动人的女子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（外形）漂亮的；（声音）优美的","en":"Something that is attractive has a pleasant appearance or sound.","ex":{"en":"The flat was small but attractive, if rather shabby","cn":"虽然有些老旧，这仍不失为一个漂亮的小公寓。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"吸引人的;值得拥有（或做）的","en":"You can describe something as attractive when it seems worth having or doing.","ex":{"en":"Co-operation was more than just an attractive option, it was an obligation","cn":"合作不仅仅是诱人的选择，它也是一种责任。"}}]},"examples":[{"en":"I like John but I don't find him attractive physically.","cn":"我喜欢约翰，不过我认为他长得并不英俊。"},{"en":"That's one of the less attractive aspects of her personality.","cn":"那是她个性中不太讨人喜欢的一面。"}]},"attempt":{"media":{"uk":"media/uk/attempt__gb_1.mp3","us":"media/us/attempt__us_1.mp3"},"oxford":{"phon":"əˈtempt","pos":"noun","senses":[{"en":"an act of trying to do something, especially something difficult, often with no success","cn":"企图；试图；尝试","g":"[countable, uncountable]","ex":{"en":"I passed my driving test at the first attempt.","cn":"我考汽车驾驶执照时一次就通过了。"}},{"en":"an act of trying to kill somebody","cn":"杀人企图","g":"[countable]","ex":{"en":"Someone has made an attempt on the president's life.","cn":"有人企图刺杀总统。"}},{"en":"an effort to do better than something, such as a very good performance in sport","cn":"（为超越某事物的）尝试，努力","g":"[countable]","ex":{"en":"his attempt on the world land speed record","cn":"他为创造陆上速度世界纪录所作的尝试"}},{"en":"a thing that you produce as a result of trying to make or achieve something","cn":"尝试的结果；努力争取的结果","g":"[countable]","ex":{"en":"She picked her first attempt at a letter out of the bin.","cn":"她从垃圾箱里捡回了她写的信的初稿。"}},{"en":"to make an effort or try to do something, especially something difficult","cn":"努力；尝试；试图","ex":{"en":"I will attempt to answer all your questions.","cn":"我将努力回答你的全部问题。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"尝试，试图（尤指做困难的事）","en":"If you attempt to do something, especially something difficult, you try to do it.","ex":{"en":"The only time that we attempted to do something like that was in the city of Philadelphia","cn":"只有在费城那次我们曾试着做那样的事。"}},{"pos":"N-COUNT 可数名词","cn":"（通常指不成功的）尝试，企图，试图","en":"If you make an attempt to do something, you try to do it, often without success.","ex":{"en":"...a deliberate attempt to destabilise the defence","cn":"经过深思熟虑的破坏该防御的尝试"}},{"pos":"N-COUNT 可数名词","cn":"杀人企图","en":"An attempt on some-one's life is an attempt to kill them.","ex":{"en":"...an attempt on the life of the former Iranian Prime Minister.","cn":"试图杀害伊朗前总理"}},{"pos":"N-COUNT 可数名词","cn":"（运动员创造纪录的）尝试，冲击","en":"In British English, if a sportsman or sportswoman makes an attempt on a sporting record, they try to beat it. In American English you say that they make an attempt to break it.","ex":{"en":"Everything is almost ready for me to make another attempt on the record.","cn":"一切几乎都已准备就绪，就等我向纪录发起再一次冲击了。"}}]},"examples":[{"en":"his attempt on the world land speed record","cn":"他为创造陆上速度世界纪录所作的尝试"},{"en":"I passed my driving test at the first attempt.","cn":"我考汽车驾驶执照时一次就通过了。"}]},"attends":{"oxford":{"phon":"əˈtend","pos":"verb","senses":[{"en":"( rather formal ) to be present at an event","cn":"出席；参加"},{"en":"( formal ) to go regularly to a place","cn":"经常去，定期去（某处）"}]},"media":{"uk":"media/uk/attend__gb_1.mp3","us":"media/us/attend__us_1.mp3"}},"athletic":{"oxford":{"phon":"æθˈletɪk","pos":"adjective","senses":[{"en":"physically strong, fit and active","cn":"健壮的","ex":{"en":"an athletic figure/build","cn":"健壮的体形／体格"}},{"en":"connected with sports such as running, jumping and throwing (= athletics)","cn":"体育运动的；田径运动的","g":"[only before noun]","lab":"British English","ex":{"en":"an athletic club/coach","cn":"运动员俱乐部／教练"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"运动的;体育的;运动员的","en":"Athletic means relating to athletes and athletics.","ex":{"en":"They have been given college scholarships purely on athletic ability","cn":"他们完全是凭体育特长才获得了大学奖学金。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"运动型的；身体健壮的","en":"An athletic person is fit, and able to perform energetic movements easily.","ex":{"en":"Xandra is an athletic 36-year-old with a 21-year-old's body","cn":"36岁的汉德拉身体健壮，有着21岁小伙子的体能。"}}]},"media":{"uk":"media/uk/athletic__gb_1.mp3","us":"media/us/athletic__us_1.mp3"},"examples":[{"en":"She moved with great athleticism about the court.","cn":"她在球场上矫健地奔跑活动。"},{"en":"an athletic club/coach","cn":"运动员俱乐部/教练"}]},"attributable":{"media":{"uk":"media/uk/attributable__gb_1.mp3","us":"media/us/attributable__us_1.mp3"},"oxford":{"phon":"əˈtrɪbjətəbl","pos":"adjective","senses":[{"en":"probably caused by the thing mentioned","cn":"可归因于；可能由于","ex":{"en":"Their illnesses are attributable to a poor diet.","cn":"他们的病可能是不良饮食所致。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可归因于…的，可归结于…的","en":"If something is attributable to an event, situation, or person, it is likely that it was caused by that event, situation or person.","ex":{"en":"10,000 deaths a year from chronic lung disease are attributable to smoking","cn":"吸烟导致每年有1万人死于慢性肺病。"}}]},"examples":[{"en":"Their illnesses are attributable to a poor diet.","cn":"他们的病可能是不良饮食所致。"},{"en":"Death was attributable to gunshot wounds.","cn":"死因可能是枪伤。"}]},"attach":{"media":{"uk":"media/uk/attach__gb_1.mp3","us":"media/us/attach__us_1.mp3"},"oxford":{"phon":"əˈtætʃ","pos":"verb","senses":[{"en":"to fasten or join one thing to another","cn":"把…固定，把…附（在…上）","g":"[transitive]","lab":"figurative","ex":{"en":"I attach a copy of my notes for your information.","cn":"我附上笔记一份供你参考。"}},{"en":"to send an electronic document with an email","cn":"给电子邮件加载附件","g":"[transitive]","ex":{"en":"I attach a copy of the spreadsheet.","cn":"我随电邮附上电子表格一份。"}},{"en":"to believe that something is important or worth thinking about","cn":"认为有重要性（或意义、价值、分量等）；重视","g":"[transitive]","ex":{"en":"I attach great importance to this research.","cn":"我认为这项研究十分重要。"}},{"en":"to join somebody for a time, sometimes when you are not welcome or have not been invited","cn":"（有时不受欢迎或未受邀请而）参加，和…在一起，缠着","g":"[transitive]","ex":{"en":"He attached himself to me at the party and I couldn't get rid of him.","cn":"在聚会上他老是缠着我，我简直无法摆脱他。"}},{"en":"to be connected with somebody/something; to connect something to something","cn":"（使）与…有联系；与…有关联","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"No one is suggesting that any health risks attach to this product.","cn":"没有人指出这个产品可能会危害健康。"}}]},"collins":{"senses":[{"pos":"","cn":"缚上；系上；贴上","en":"If you attach something to an object, you join it or fasten it to the object.","ex":{"en":"We attach labels to things before we file them away","cn":"存档前，我们先贴上标签。"}},{"pos":"","cn":"（通常未受邀请而）加入，和…在一起，缠着","en":"If someone attaches himself or herself to you, they join you and stay with you, often without being invited to do so.","ex":{"en":"Natasha attached herself to the film crew filming at her orphanage.","cn":"娜塔莎紧紧缠着在孤儿院拍摄电影的工作人员不放。"}},{"pos":"","cn":"赋予;认为…具有;为…所有","en":"If people attach a quality to someone or something, or if it attaches to them, people consider that they have that quality.","ex":{"en":"The authorities attached much significance to his visit.","cn":"当局非常重视他的访问。"}},{"pos":"","cn":"附加，附带（条件）","en":"If you attach conditions to something such as an agreement, you state that specific things must be done before the agreement is valid.","ex":{"en":"Activists are pressing the banks to attach political conditions to the signing of any new agreement","cn":"激进分子强烈要求银行在签署任何新协议前要考虑政治条件。"}},{"pos":"","cn":"（计算机中）附上，粘贴（附件）","en":"In computing, if you attach a file to a message that you send to someone, you send it with the message but separate from it.","ex":{"en":"It is possible to attach executable program files to e-mail.","cn":"可以在电子邮件里附上可执行程序文件。"}},{"pos":"See also:","cn":"","en":"no strings attached→see: ;"}]},"examples":[{"en":"He attached himself to me at the party and I couldn't get rid of him.","cn":"在聚会上他老是缠着我，我简直无法摆脱他。"},{"en":"No one is suggesting that any health risks attach to this product.","cn":"没有人指出这个产品可能会危害健康。"}]},"attending":{"oxford":{"phon":"əˈtend","pos":"verb","senses":[{"en":"( rather formal ) to be present at an event","cn":"出席；参加"},{"en":"( formal ) to go regularly to a place","cn":"经常去，定期去（某处）"}]},"media":{"uk":"media/uk/attend__gb_1.mp3","us":"media/us/attend__us_1.mp3"}},"attribute":{"media":{"uk":"media/uk/attribute__gb_1.mp3","us":"media/us/attribute__us_1.mp3"},"oxford":{"phon":"əˈtrɪbjuːt","pos":"verb","senses":[{"en":"to say or believe that something is the result of a particular thing","cn":"把…归因于；认为…是由于","ex":{"en":"She attributes her success to hard work and a little luck.","cn":"她认为她的成功来自勤劳和一点运气。"}},{"en":"to say or believe that somebody is responsible for doing something, especially for saying, writing or painting something","cn":"认为是…所为（或说、写、作）","ex":{"en":"This play is usually attributed to Shakespeare.","cn":"人们通常认为这部戏剧是莎士比亚所写。"}},{"en":"to regard a quality or feature as belonging to somebody/something","cn":"将（特质或特点）归属于","ex":{"en":"The committee refused to attribute blame without further information.","cn":"如果没有进一步的消息，委员会拒绝归罪于任何人。"}},{"en":"a quality or feature of somebody/something","cn":"属性；性质；特征","ex":{"en":"Patience is one of the most important attributes in a teacher.","cn":"耐心是教师最重要的品质之一。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"把…归因于;把…归咎于","en":"If you attribute something to an event or situation, you think that it was caused by that event or situation.","ex":{"en":"Women tend to attribute their success to external causes such as luck.","cn":"女性倾向于将她们的成功归因于外部因素，比如运气。"}},{"pos":"VERB 动词","cn":"将（品质或特征）加于…;认为…为…所有","en":"If you attribute a particular quality or feature to someone or something, you think that they have got it.","ex":{"en":"People were beginning to attribute superhuman qualities to him.","cn":"人们开始觉得他超人一等。"}},{"pos":"VERB 动词","cn":"认为(文章、艺术品或评论）出自…","en":"If a piece of writing, a work of art, or a remark is attributed to someone, people say that they wrote it, created it, or said it.","ex":{"en":"This, and the remaining frescoes, are not attributed to Giotto.","cn":"这个，还有那些残存的湿壁画，都不是乔托的作品。"}},{"pos":"N-COUNT 可数名词","cn":"（人或物的）品质，特征","en":"An attribute is a quality or feature that someone or something has.","ex":{"en":"Cruelty is a normal attribute of human behaviour","cn":"残忍是人的天性之一。"}}]},"examples":[{"en":"The committee refused to attribute blame without further information.","cn":"如果没有进一步的情况，委员会拒绝归罪于任何人。"},{"en":"This play is usually attributed to Shakespeare.","cn":"人们通常认为这出戏剧是莎士比亚所写。"}]},"attrition":{"media":{"uk":"media/uk/attrition__gb_1.mp3","us":"media/us/attrition__us_1.mp3"},"oxford":{"phon":"əˈtrɪʃn","pos":"noun","senses":[{"en":"a process of making somebody/something, especially your enemy, weaker by repeatedly attacking them or creating problems for them","cn":"（尤指给敌人造成的）削弱，消耗","ex":{"en":"It was a war of attrition.","cn":"这是一场消耗战。"}},{"en":"the process of reducing the number of people who are employed by an organization by, for example, not replacing people who leave their jobs","cn":"自然减员","lab":"especially North American English"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（对敌人造成的）削弱，耗损","en":"Attrition is a process in which you steadily reduce the strength of an enemy by continually attacking them.","ex":{"en":"The rebels have declared a ceasefire in their war of attrition against the government.","cn":"在与政府的消耗战中，反叛者宣布停火。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"人员减缩;人员流失","en":"At a university or place of work, attrition is the decrease in the number of students or employees caused by people leaving and not being replaced.","ex":{"en":"The company plans to cut a quarter of its workforce over six years through natural attrition and fewer hirings.","cn":"公司计划在6年内通过人员自然流失和减少雇用使员工总数减少1/4。"}}]},"examples":[{"en":"It was a war of attrition.","cn":"这是一场消耗战。"},{"en":"Staff reductions could be achieved through attrition and early retirements.","cn":"减少员工数量可以通过自然减员和提前退休来实现。"}]},"attendance":{"media":{"uk":"media/uk/attendance__gb_1.mp3","us":"media/us/attendance__us_1.mp3"},"oxford":{"phon":"əˈtendəns","pos":"noun","senses":[{"en":"the act of being present at a place, for example at school","cn":"出席；参加；上学；到场","g":"[uncountable, countable]","ex":{"en":"Attendance at these lectures is not compulsory.","cn":"这些课不是硬性规定要听的。"}},{"en":"the number of people present at an organized event","cn":"出席人数","g":"[countable, uncountable]","ex":{"en":"high/low/falling/poor attendances","cn":"出席的人数多／少／下降／很少"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"出席;参加;出勤","en":"Someone's attendance at an event or an institution is the fact that they are present at the event or go regularly to the institution.","ex":{"en":"Her attendance at school was sporadic.","cn":"她三天两头旷课。"}},{"pos":"N-VAR 可变名词","cn":"出席的人数","en":"The attendance at an event is the number of people who are present at it.","ex":{"en":"Average weekly cinema attendance in February was 2.41 million","cn":"2月份，平均每周的观影人数为241万。"}},{"pos":"PHRASE 短语","cn":"到（某地）；出席（某活动）","en":"If someone is in attendance at a place or an event, they are there.","ex":{"en":"Councillor Paul Tisley will be in attendance at the start of the meeting to welcome us","cn":"议员保罗·提斯里将在会议开始时出席，以欢迎我们。"}},{"pos":"PHRASE 短语","cn":"陪同；陪伴","en":"If someone is in attendance on an important person, they are accompanying that person as a servant or assistant.","ex":{"en":"He lived in considerable style, travelling widely, usually with a cook, valet, butler and chauffeur in attendance.","cn":"他活得相当潇洒，通常带着厨师、用人、管家和司机到处游玩。"}}]},"examples":[{"en":"Teachers must keep a record of students' attendances.","cn":"老师必须记录学生的出席情况。"},{"en":"Attendance at these lectures is not compulsory.","cn":"这些课不是硬性规定要听的。"}]},"athlete":{"media":{"uk":"media/uk/athlete__gb_1.mp3","us":"media/us/athlete__us_1.mp3"},"oxford":{"phon":"ˈæθliːt","pos":"noun","senses":[{"en":"a person who competes in sports","cn":"运动员","ex":{"en":"Olympic athletes","cn":"奥运会运动员"}},{"en":"a person who competes in sports such as running, jumping and throwing","cn":"田径运动员","lab":"British English","ex":{"en":"He played baseball and basketball and excelled as a track athlete.","cn":"他会打棒球和篮球，还是个优秀的径赛运动员。"}},{"en":"a person who is good at sports and physical exercise","cn":"擅长运动的人；健儿","ex":{"en":"She is a natural athlete.","cn":"她是个天生的运动健将。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指田径项目的）运动员，运动选手","en":"An athlete is a person who does a sport, especially athletics, or track and field events.","ex":{"en":"Daley Thompson was a great athlete.","cn":"戴利·汤普森是位著名的运动员。"}},{"pos":"N-COUNT 可数名词","cn":"运动健儿;身强力壮的人","en":"You can refer to someone who is fit and athletic as an athlete .","ex":{"en":"I was no athlete.","cn":"我根本不是当运动员的料。"}}]},"examples":[{"en":"She is a natural athlete.","cn":"她是个天生的运动健将。"},{"en":"Olympic athletes","cn":"奥运会运动员"}]},"attire":{"media":{"uk":"media/uk/attire__gb_1.mp3","us":"media/us/attire__us_1.mp3"},"oxford":{"phon":"əˈtaɪə(r)","pos":"noun","senses":[{"en":"clothes, especially fine or formal ones","cn":"礼服；正式服装","ex":{"en":"dressed in formal evening attire","cn":"穿着晚礼服"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"服装;衣服","en":"Your attire is the clothes you are wearing.","ex":{"en":"...seven women dressed in their finest attire.","cn":"七个盛装打扮的女子"}}]},"examples":[{"en":"dressed in formal evening attire","cn":"穿着晚礼服"},{"en":"business attire","cn":"商务着装﹐正装"}]},"attacking":{"oxford":{"phon":"əˈtæk","pos":"noun","senses":[{"en":"an act of using violence to try to hurt or kill sb","cn":"袭击；攻击"},{"en":"an act of trying to kill or injure the enemy in war, using weapons such as guns and bombs （","cn":"在战争中使用武器的）进攻，攻击"}]},"media":{"uk":"media/uk/attack__gb_1.mp3","us":"media/us/attack__us_1.mp3"}},"atop":{"media":{"uk":"media/uk/atop__gb_1.mp3","us":"media/us/atop__us_1.mp3"},"oxford":{"phon":"əˈtɒp","pos":"preposition","senses":[{"en":"on top of; at the top of","cn":"在…顶上","ex":{"en":"a flag high atop a pole","cn":"高挂在旗杆顶端的旗子"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…顶上;在…上面","en":"If something is atop something else, it is on top of it.","ex":{"en":"Under the newspaper, atop a sheet of paper, lay an envelope.","cn":"在报纸下面的一张纸上放着一个信封。"}}]},"examples":[{"en":"a scoop of ice cream atop a slice of apple pie","cn":"一片苹果馅饼上面的一勺冰淇淋"},{"en":"a flag high atop a pole","cn":"高挂在旗杆顶端的旗子"}]},"attest":{"oxford":{"phon":"əˈtest","pos":"verb","senses":[{"en":"to show or prove that something is true","cn":"证实；是…的证据","g":"[intransitive, transitive]","ex":{"en":"Contemporary accounts attest to his courage and determination.","cn":"当时的报道证实了他的勇气和决心。"}},{"en":"to state that you believe that something is true or what somebody claims it is, for example in court","cn":"作证，证明（如在法庭上）","g":"[transitive]","ex":{"en":"to attest a will","cn":"就遗嘱作见证"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"说明，表示，证明（某事属实）","en":"To attest something or attest to something means to say, show, or prove that it is true.","ex":{"en":"Police records attest to his long history of violence","cn":"警方记录证明他有长期从事暴力活动的前科。"}}]},"media":{"uk":"media/uk/attest__gb_1.mp3","us":"media/us/attest__us_1.mp3"},"examples":[{"en":"Contemporary accounts attest to his courage and determination.","cn":"当时的报道证实了他的勇气和决心。"},{"en":"The signature was attested by two witnesses.","cn":"这个签名有两名见证人。"}]},"attract":{"media":{"uk":"media/uk/attract__gb_1.mp3","us":"media/us/attract__us_1.mp3"},"oxford":{"phon":"əˈtrækt","pos":"verb","senses":[{"en":"if you are attracted by something, it interests you and makes you want it; if you are attracted by somebody, you like or admire them","cn":"吸引；使喜爱；引起…的好感（或爱慕）","g":"[usually passive]","ex":{"en":"I had always been attracted by the idea of working abroad.","cn":"我总是向往去国外工作。"}},{"en":"to have a sexual or romantic interest in somebody","cn":"迷恋；被诱惑","ex":{"en":"I am not attracted to him at all.","cn":"我对他一点兴趣也没有。"}},{"en":"to make somebody/something come somewhere or take part in something","cn":"招引","ex":{"en":"Officials hope to attract more tourists to the area.","cn":"官员们希望把更多的游客吸引到这个地区来。"}},{"en":"to make people have a particular reaction","cn":"引起（反应）","ex":{"en":"This proposal has attracted a lot of interest.","cn":"这个提案引起了人们很大的兴趣。"}},{"en":"if a magnet or gravity attracts something, it makes it move towards it","cn":"吸引","lab":"physics"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"吸引","en":"If something attracts people or animals, it has features that cause them to come to it.","ex":{"en":"The Cardiff Bay project is attracting many visitors","cn":"加的夫海湾项目吸引了众多游客。"}},{"pos":"VERB 动词","cn":"引起…的注意（或兴趣、赞赏等）；诱惑","en":"If someone or something attracts you, they have particular qualities which cause you to like or admire them. If a particular quality attracts you to a person or thing, it is the reason why you like them.","ex":{"en":"He wasn't sure he'd got it right, although the theory attracted him by its logic","cn":"该理论的逻辑性吸引了他，但他不能确定自己的理解是否正确。"}},{"pos":"VERB 动词","cn":"引起…的好感;吸引;诱惑","en":"If you are attracted to someone, you are interested in them sexually.","ex":{"en":"In spite of her hostility, she was attracted to him","cn":"尽管自己心存敌意，她还是为他所吸引。"}},{"pos":"VERB 动词","cn":"吸引，招引（支持、关注或金钱）","en":"If something attracts support, publicity, or money, it receives support, publicity, or money.","ex":{"en":"President Mwinyi said his country would also like to attract investment from private companies","cn":"姆维尼总统说他的国家同样愿意吸收来自私营公司的投资。"}},{"pos":"VERB 动词","cn":"（物体间）吸引，产生引力","en":"If one object attracts another object, it causes the second object to move towards it.","ex":{"en":"Anything with strong gravity attracts other things to it.","cn":"任何有较强重力的物体都会对其他物体产生引力。"}},{"pos":"","cn":"","en":"to attract someone's attention→see: ;"}]},"examples":[{"en":"The warm damp air attracts a lot of mosquitoes.","cn":"温暖潮湿的空气招来了大量蚊子。"},{"en":"What first attracted me to her was her sense of humour.","cn":"她首先吸引我的是她的幽默感。"}]},"attitude":{"media":{"uk":"media/uk/attitude__gb_1.mp3","us":"media/us/attitude__us_1.mp3"},"oxford":{"phon":"ˈætɪtjuːd","pos":"noun","senses":[{"en":"the way that you think and feel about somebody/something; the way that you behave towards somebody/something that shows how you think and feel","cn":"态度；看法","g":"[countable]","ex":{"en":"These societies have to change their attitudes towards women.","cn":"这些社团必须改变对待妇女的态度。"}},{"en":"confident, sometimes aggressive behaviour that shows you do not care about other people’s opinions and that you want to do things in an individual way","cn":"我行我素的做派","g":"[uncountable]","ex":{"en":"You'd better get rid of that attitude and shape up, young man.","cn":"年轻人，你最好改掉那种态度，学学好。"}},{"en":"a position of the body","cn":"姿势","g":"[countable]","lab":"formal","ex":{"en":"Her hands were folded in an attitude of prayer.","cn":"她双手合拢成祈祷姿势。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（尤指从行为中表现出来的）态度，看法","en":"Your attitude to something is the way that you think and feel about it, especially when this shows in the way you behave.","ex":{"en":"...the general change in attitude towards handicapped people","cn":"对残疾人态度的整体转变"}},{"pos":"N-UNCOUNT 不可数名词","cn":"个人风格;（尤指）咄咄逼人的作派","en":"If you refer to someone as a person with attitude, you mean that they have a striking and individual style of behaviour, especially a forceful or aggressive one.","ex":{"en":"Patti Smith and Janis Joplin did it all years ago and they were women with attitude and talent.","cn":"帕蒂·史密斯和詹妮斯·乔普林多年前就这样做过，她们当时是两位个性鲜明的才女。"}},{"pos":"PHRASE 短语","cn":"思想方法;感情","en":"Your attitude of mind is your general way of thinking and feeling.","ex":{"en":"Writing calls for a critical attitude of mind that he did not possess.","cn":"写作需要有批判性思维，而这正是他所不具备的。"}}]},"examples":[{"en":"to have a good/bad/positive/negative attitude towards sb/sth","cn":"对某人（或事物）持好的/坏的/肯定的/否定的态度"},{"en":"You're taking a pretty selfish attitude over this, aren't you?","cn":"你对这个问题的看法相当自私，对不对？"}]},"attend":{"media":{"uk":"media/uk/attend__gb_1.mp3","us":"media/us/attend__us_1.mp3"},"oxford":{"phon":"əˈtend","pos":"verb","senses":[{"en":"to be present at an event","cn":"出席；参加","g":"[intransitive, transitive]","lab":"rather formal","ex":{"en":"We'd like as many people as possible to attend.","cn":"我们希望出席的人越多越好。"}},{"en":"to go regularly to a place","cn":"经常去，定期去（某处）","g":"[transitive, intransitive]","lab":"formal","ex":{"en":"Our children attend the same school.","cn":"我们的孩子上同一所学校。"}},{"en":"to pay attention to what somebody is saying or to what you are doing","cn":"注意；专心","g":"[intransitive]","lab":"formal","ex":{"en":"She hadn't been attending during the lesson.","cn":"上课时她一直不专心。"}},{"en":"to happen at the same time as something","cn":"伴随发生","g":"[transitive]","lab":"formal","ex":{"en":"She dislikes the loss of privacy that attends TV celebrity.","cn":"她不喜欢成为电视名人后随之失去个人隐私。"}},{"en":"to be with somebody and help them","cn":"随同；陪同","g":"[transitive]","lab":"formal","ex":{"en":"The president was attended by several members of his staff.","cn":"总统有几名幕僚随从。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"出席；参加","en":"If you attend a meeting or other event, you are present at it.","ex":{"en":"Thousands of people attended the funeral","cn":"数千人参加了葬礼。"}},{"pos":"VERB 动词","cn":"去（学校、教堂等）；上（学）","en":"If you attend an institution such as a school, college, or church, you go there regularly.","ex":{"en":"They attended college together at the University of Pennsylvania.","cn":"他们一起就读于宾夕法尼亚大学。"}},{"pos":"VERB 动词","cn":"处理，料理（事情）；照顾，护理（受伤的人）","en":"If you attend to something, you deal with it. If you attend to someone who is hurt or injured, you care for them.","ex":{"en":"The staff will helpfully attend to your needs","cn":"工作人员会帮忙满足您的需求。"}}]},"examples":[{"en":"She dislikes the loss of privacy that attends TV celebrity.","cn":"她不喜欢成为电视名人后随之失去个人隐私。"},{"en":"A nurse attended to his needs constantly.","cn":"有一位护士经常照料他的需要。"}]},"attuned":{"media":{"uk":"media/uk/attuned__gb_1.mp3","us":"media/us/attuned__us_1.mp3"},"oxford":{"phon":"əˈtjuːnd","pos":"adjective","senses":[{"en":"familiar with somebody/something so that you can understand or recognize them or it and act in an appropriate way","cn":"熟悉；适应；习惯","ex":{"en":"She wasn't yet attuned to her baby's needs.","cn":"她还没有熟悉她宝宝的需求。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"适应的;理解的;与…合拍的","en":"If you are attuned to something, you can understand and appreciate it.","ex":{"en":"I have become attuned to Carlisle's industrial past","cn":"我对于卡莱尔市过去的工业史已经有所了解。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"听得出的;习惯于（某种声音）的","en":"If your ears are attuned to a sound, you can hear it and recognize it quickly.","ex":{"en":"Their ears were still attuned to the sounds of the London suburb.","cn":"他们依然很熟悉伦敦市郊的喧闹声。"}}]},"examples":[{"en":"She wasn't yet attuned to her baby's needs.","cn":"她还没有熟悉她宝宝的需要。"},{"en":"British companies still aren’t really attuned to the needs of the Japanese market.","cn":"英国公司还没有完全熟悉日本市场的需求。"}]},"athletes":{"oxford":{"phon":"ˈæθliːt","pos":"noun","senses":[{"en":"a person who competes in sports","cn":"运动员"},{"en":"( BrE ) a person who competes in sports such as running and jumping","cn":"田径运动员"}]},"media":{"uk":"media/uk/athlete__gb_1.mp3","us":"media/us/athlete__us_1.mp3"}},"atmosphere":{"media":{"uk":"media/uk/atmosphere__gb_1.mp3","us":"media/us/atmosphere__us_1.mp3"},"oxford":{"phon":"ˈætməsfɪə(r)","pos":"noun","senses":[{"en":"the mixture of gases that surrounds the earth","cn":"（围绕地球的）大气，大气圈，大气层","g":"[singular]","ex":{"en":"Wind power doesn't release carbon dioxide into the atmosphere.","cn":"风电不会往大气中释放二氧化碳。"}},{"en":"a mixture of gases that surrounds another planet or a star","cn":"（围绕其他天体的）气体","g":"[countable]","ex":{"en":"Saturn’s atmosphere","cn":"土星的大气"}},{"en":"the air in a room or in a small space; the air around a place","cn":"（房间、封闭空间或某处的）空气","g":"[countable]","ex":{"en":"a smoky/stuffy atmosphere","cn":"烟雾弥漫的／闷热的空气"}},{"en":"the feeling or mood that you have in a particular place or situation; a feeling between two people or in a group of people","cn":"气氛；氛围","g":"[countable, singular, uncountable]","ex":{"en":"Before the parade, the atmosphere was electric.","cn":"游行之前，气氛十分热烈。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大气;大气层;大气圈","en":"A planet's atmosphere is the layer of air or other gases around it.","ex":{"en":"...dangerous levels of pollution in the Earth's atmosphere","cn":"地球大气层污染程度严重"}},{"pos":"N-COUNT 可数名词","cn":"（呼吸的）空气","en":"The atmosphere of a place is the air that you breathe there.","ex":{"en":"These gases pollute the atmosphere of towns and cities.","cn":"这些气体污染了城镇的空气。"}},{"pos":"N-SING 单数名词","cn":"氛围；环境","en":"The atmosphere of a place is the general impression that you get of it.","ex":{"en":"Pale wooden floors and plenty of natural light add to the relaxed atmosphere","cn":"淡色木地板和充足的自然光平添了几分轻松的氛围。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（地方或事件的）情调，魅力","en":"If a place or an event has atmosphere, it is interesting.","ex":{"en":"The old harbour is still full of atmosphere and well worth visiting.","cn":"这座古老的港口依然充满了情趣，颇值得一游。"}}]},"examples":[{"en":"The hotel offers a friendly atmosphere and personal service.","cn":"这家旅馆服务周到，使客人感到宾至如归。"},{"en":"The children grew up in an atmosphere of violence and insecurity.","cn":"这些孩子在暴力和无安全感的环境中长大。"}]},"ate":{"collins":{"senses":[{"pos":"","cn":"","en":"Ate is the past tense of eat."}]},"media":{"uk":"media/uk/ate__gb_1.mp3","us":"media/us/ate__us_1.mp3"},"oxford":{"phon":"ət","pos":"suffix","senses":[{"en":"full of or having the quality of","cn":"充满…的；有…性质的","ex":{"en":"passionate","cn":"充满热情的"}},{"en":"to give the thing or quality mentioned to","cn":"赋予某物；给予…性质","ex":{"en":"hyphenate","cn":"用连字符连接"}},{"en":"the status or function of","cn":"（表示地位或职能）","ex":{"en":"a doctorate","cn":"博士学位"}},{"en":"a group with the status or function of","cn":"（表示有地位或职能的群体）","ex":{"en":"the electorate","cn":"全体选民"}},{"en":"a salt formed by the action of a particular acid","cn":"（酸作用形成的）盐","lab":"chemistry","ex":{"en":"sulphate","cn":"硫酸盐"}}]}},"atomic":{"oxford":{"phon":"əˈtɒmɪk","pos":"adjective","senses":[{"en":"relating to atoms or an atom","cn":"原子的；与原子有关的","ex":{"en":"atomic structure","cn":"原子结构"}},{"en":"relating to the energy that is produced when atoms are split; related to weapons that use this energy","cn":"原子能的；原子武器的","ex":{"en":"atomic energy/power","cn":"原子能／动力"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"核能的；原子能的","en":"Atomic means relating to power that is produced from the energy released by splitting atoms.","ex":{"en":"...atomic energy.","cn":"原子能"}},{"pos":"ADJ 形容词","cn":"原子的;与原子有关的","en":"Atomic means relating to the atoms of substances."}]},"media":{"uk":"media/uk/atomic__gb_1.mp3","us":"media/us/atomic__us_1.mp3"},"examples":[{"en":"atomic energy/power","cn":"原子能/动力"},{"en":"atomic structure","cn":"原子结构"}]},"attempted":{"media":{"uk":"media/uk/attempted__gb_1.mp3","us":"media/us/attempted__us_1.mp3"},"oxford":{"phon":"əˈtemptɪd","pos":"adjective","senses":[{"en":"that somebody has tried to do but without success","cn":"未遂的","ex":{"en":"attempted murder/robbery/kidnapping","cn":"企图谋杀/抢劫/绑架"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（犯罪、不法行为）未遂的，未得手的","en":"An attempted crime or unlawful action is an unsuccessful effort to commit the crime or action.","ex":{"en":"...a case of attempted murder","cn":"谋杀未遂案"}}]},"examples":[{"en":"attempted rape/murder/robbery","cn":"企图强奸/谋杀/抢劫"}]},"attitudes":{"oxford":{"phon":"ˈætɪtjuːd","pos":"noun","senses":[{"en":"the way that you think and feel about sb/sth; the way that you behave towards sb/sth that shows how you think and feel","cn":"态度；看法"},{"en":"confident, sometimes aggressive behaviour that shows you do not care about other people's opinions and that you want to do things in an individual way","cn":"我行我素的做派"}]}},"attempts":{"oxford":{"phon":"əˈtempt","pos":"noun","senses":[{"en":"an act of trying to do sth, especially sth difficult, often with no success","cn":"企图；试图；尝试"},{"en":"an act of trying to kill sb","cn":"杀人企图"}]}},"attained":{"oxford":{"phon":"əˈteɪn","pos":"verb","senses":[{"en":"to succeed in getting sth, usually after a lot of effort （","cn":"通常经过努力）获得，得到"},{"en":"to reach a particular age, level or condition","cn":"达到（某年龄、水平、状况）"}]}},"attracting":{"oxford":{"phon":"əˈtrækt","pos":"verb","senses":[{"en":"if you are attracted by sth, it interests you and makes you want it; if you are attracted by sb, you like or admire them","cn":"吸引；使喜爱；引起 … 的好感（或爱慕）"},{"en":"to make sb/sth come somewhere or take part in sth","cn":"招引"}]}},"attaches":{"oxford":{"phon":"əˈtætʃ","pos":"verb","senses":[{"en":"to fasten or join one thing to another","cn":"把 … 固定，把 … 附（在 … 上）"},{"en":"to believe that sth is important or worth thinking about","cn":"认为有重要性（或意义、价值、分量等）；重视"}]}},"attacks":{"oxford":{"phon":"əˈtæk","pos":"noun","senses":[{"en":"an act of using violence to try to hurt or kill sb","cn":"袭击；攻击"},{"en":"an act of trying to kill or injure the enemy in war, using weapons such as guns and bombs （","cn":"在战争中使用武器的）进攻，攻击"}]}},"attracted":{"oxford":{"phon":"əˈtrækt","pos":"verb","senses":[{"en":"if you are attracted by sth, it interests you and makes you want it; if you are attracted by sb, you like or admire them","cn":"吸引；使喜爱；引起 … 的好感（或爱慕）"},{"en":"to make sb/sth come somewhere or take part in sth","cn":"招引"}]}},"attempting":{"oxford":{"phon":"əˈtempt","pos":"noun","senses":[{"en":"an act of trying to do sth, especially sth difficult, often with no success","cn":"企图；试图；尝试"},{"en":"an act of trying to kill sb","cn":"杀人企图"}]}},"attendees":{"oxford":{"phon":"ˌætenˈdiː","pos":"noun","senses":[{"en":"a person who attends a meeting, etc.","cn":"出席者；在场者"}]}},"attended":{"oxford":{"phon":"əˈtend","pos":"verb","senses":[{"en":"( rather formal ) to be present at an event","cn":"出席；参加"},{"en":"( formal ) to go regularly to a place","cn":"经常去，定期去（某处）"}]}},"attaching":{"oxford":{"phon":"əˈtætʃ","pos":"verb","senses":[{"en":"to fasten or join one thing to another","cn":"把 … 固定，把 … 附（在 … 上）"},{"en":"to believe that sth is important or worth thinking about","cn":"认为有重要性（或意义、价值、分量等）；重视"}]}},"attacked":{"oxford":{"phon":"əˈtæk","pos":"noun","senses":[{"en":"an act of using violence to try to hurt or kill sb","cn":"袭击；攻击"},{"en":"an act of trying to kill or injure the enemy in war, using weapons such as guns and bombs （","cn":"在战争中使用武器的）进攻，攻击"}]}},"attracts":{"oxford":{"phon":"əˈtrækt","pos":"verb","senses":[{"en":"if you are attracted by sth, it interests you and makes you want it; if you are attracted by sb, you like or admire them","cn":"吸引；使喜爱；引起 … 的好感（或爱慕）"},{"en":"to make sb/sth come somewhere or take part in sth","cn":"招引"}]}},"atlantic":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the Atlantic Ocean. British people sometimes use phrases such as ‘across the Atlantic’ or ‘on the other side of the Atlantic’ when they are talking about the US, and Americans use these phrases when they are talking about western Europe, especially the UK","cn":""},{"en":"in, near, or from the Atlantic Ocean","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/p028-000001812.mp3","us":"media/ldoce/hwd/ame/3/lpd_atlantic__a_.mp3"},"examples":[{"en":"Scientists from both sides of the Atlantic will meet next month in New York.","cn":""},{"en":"the southern Atlantic coast","cn":""}]},"atheist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"无神论者","en":"An atheist is a person who believes that there is no God."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does not believe in any god","cn":""},{"en":"someone who believes that it is impossible to be certain whether God exists or not","cn":""},{"en":"the belief that God does not exist","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"An atheist believes there is no such thing as god, or any other deity."}]},"collocations":{"phrases":["ADJ. committed, confirmed, dedicated"]},"media":{"uk":"media/ldoce/hwd/bre/e/a435new3.mp3","us":"media/ldoce/hwd/ame/6/ld41atheism.mp3"},"oxford":{"phon":"ˈeɪθiɪst","pos":"noun","senses":[{"en":"a person who believes that God or gods do not exist","cn":"无神论者"}]}},"athletics":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"田径运动","en":"Athletics refers to track and field sports such as running, the high jump, and the javelin.","ex":{"en":"As the modern Olympics grew in stature, so too did athletics.","cn":"随着现代奥林匹克运动会声名远扬，田径运动也越来越受关注。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"体育运动；竞技","en":"Athletics refers to any kind of physical sports, exercise, or games.","ex":{"en":"...students who play intercollegiate athletics.","cn":"参加大学校际体育竞赛的学生"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"sports such as running and jumping","cn":"田径运动"},{"en":"physical activities such as sports and exercise","cn":"体育运动"}]},"collocations":{"phrases":["ADJ. indoor, outdoor | junior, senior | amateur, schools | international, world","VERB + ATHLETICS compete in, do, take part in My daughter wants to compete in athletics. | take up She didn't take up athletics until she wa","ATHLETICS + NOUN championships, competition, event, meet, meeting | club, federation | stadium, track | star | coach | club, team | official"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeathletics.mp3","us":"media/ldoce/hwd/ame/f/athletics.mp3","img":["media/pic/athletics_comp.jpg"]},"examples":[{"en":"students involved in all forms of college athletics","cn":"参加各种大学体育运动的学生"}],"oxford":{"phon":"æθˈletɪks","pos":"noun","senses":[{"en":"sports such as running, jumping and throwing that people compete in","cn":"田径运动","lab":"British English","ex":{"en":"My daughter wants to compete in athletics.","cn":"我女儿想参加田径竞赛。"}},{"en":"any sports that people compete in","cn":"体育运动","lab":"North American English","ex":{"en":"students involved in all forms of college athletics","cn":"参加各种大学体育运动的学生"}}]}},"attainable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可达到的；可得到的","en":"Something that is attainable can be achieved.","ex":{"en":"It is unrealistic to believe perfection is an attainable goal.","cn":"相信完美可以企及是不现实的。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"something that is possible , can be done","cn":""},{"en":"if something can be done , it is possible to do it","cn":""},{"en":"one of the things that you could try to do","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"You can do it, no doubt about it. Yes, your goal is attainable : within reach and not too difficult to achieve."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. fully, perfectly We believe that this level of performance is fully attainable. | easily, readily","PREP. by This standard of English should be easily attainable by every child in the class."]},"media":{"uk":"media/ldoce/hwd/bre/d/attain0205.mp3","us":"media/ldoce/hwd/ame/d/attain.mp3"},"examples":[{"en":"This standard is easily attainable by most students.","cn":"这个标准大多数学生都容易达到。"},{"en":"attainable goals/objectives/targets","cn":"可达到的目标"}],"oxford":{"phon":"əˈteɪnəbl","pos":"adjective","senses":[{"en":"that you can achieve","cn":"可达到的；可获得的","ex":{"en":"attainable goals/objectives/targets","cn":"可达到的目标"}}]}},"atrocity":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"暴行；滔天罪行","en":"An atrocity is a very cruel, shocking action.","ex":{"en":"The killing was cold-blooded, and those who committed this atrocity should be tried and punished.","cn":"杀戮异常残暴。那些犯下如此暴行的人都应该受到审判和惩罚。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unusually cruel and violent action, usually against someone who has done nothing wrong, that is unacceptable even during a time of war","cn":""},{"en":"an extremely bad, and often cruel and unfair action that people think is shocking","cn":""},{"en":"cruel treatment or behaviour","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Atrocities , acts of outrageous cruelty, are often committed during wars and armed conflicts."}]},"collocations":{"phrases":["ADJ. appalling, dreadful, terrible, worst one of the worst atrocities of the war | alleged | terrorist","VERB + ATROCITY be responsible for, carry out, commit, perpetrate In the war, both sides committed atrocities. | suffer","ATROCITY + VERB occur, take place","ATROCITY + NOUN stories","PREP. ~ against atrocities against the civilian population | ~ by reports of atrocities by gunmen","PHRASES accounts/allegations/reports of atrocities"]},"media":{"uk":"media/ldoce/hwd/bre/f/atrocity0205.mp3","us":"media/ldoce/hwd/ame/8/atrocity.mp3"},"oxford":{"phon":"əˈtrɒsəti","pos":"noun","senses":[{"en":"a cruel and violent act, especially in a war","cn":"（尤指战争中的）残暴行为","ex":{"en":"In the war, both sides committed atrocities.","cn":"在战争中，双方都犯下暴行。"}}]}},"attachment":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"喜欢;爱慕;忠诚","en":"If you have an attachment to someone or something, you are fond of them or loyal to them.","ex":{"en":"As a teenager she formed a strong attachment to one of her teachers","cn":"少女时代的她曾迷上了自己的一个老师。"}},{"pos":"N-COUNT 可数名词","cn":"（机器的）附件，附加装置","en":"An attachment is a device that can be fixed onto a machine in order to enable it to do different jobs.","ex":{"en":"Some models come with attachments for dusting.","cn":"一些模型上附带了除尘器。"}},{"pos":"N-VAR 可变名词","cn":"（临时的）隶属，委派","en":"If someone is on attachment to another company, department, or place, they are working there temporarily.","ex":{"en":"During her course she worked on attachment for six months at Kew Gardens","cn":"在上学期间，她曾临时到基尤植物园工作了6个月。"}},{"pos":"N-COUNT 可数名词","cn":"（文件）附件","en":"An attachment is an extra document that is added to another document.","ex":{"en":"Justice Fitzgerald included a 120-page discussion paper as an attachment to the annual report.","cn":"在年度报告上，法官菲茨杰拉德附上了一篇长达120页的讨论稿。"}},{"pos":"N-COUNT 可数名词","cn":"（邮件）附件","en":"In computing, an attachment is a file which is attached separately to a message that you send to someone.","ex":{"en":"When you send an e-mail you can also send a sound or graphic file as an attachment.","cn":"在发送电子邮件时，你也可以附上一份声音或图片文件。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a message sent using the email system","cn":""},{"en":"an email – used when it is obvious that you are talking about a message sent by email, rather than a message sent by some other method","cn":""},{"en":"a document or file that is sent with an email","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Attachment is a sticky word: an email attachment fastens a file to an email, while someone who has an attachment to email loves email. Attachment brings things together."}]},"collocations":{"phrases":["ADJ. close, deep, passionate, special, strong | enduring, lasting | emotional, romantic, sentimental","VERB + ATTACHMENT feel, have I feel no attachment to the countryside. | develop, form Prisoners can develop attachments to their warders.","PREP. to her strong attachment to her mother"]},"media":{"uk":"media/ldoce/hwd/bre/9/attachment0205.mp3","us":"media/ldoce/hwd/ame/7/attachment.mp3"},"examples":[{"en":"All cars built since 1981 have points for the attachment of safety restraints.","cn":"自 1981 年起生产的轿车都有安全保护装置的连接点。"},{"en":"They had to check the strength of the seat attachments to the floor of the plane.","cn":"他们需要检查座椅与飞机舱面固定接头的强度。"}],"oxford":{"phon":"əˈtætʃmənt","pos":"noun","senses":[{"en":"a document that you send to somebody using email","cn":"（用电子邮件发送的）附件","g":"[countable]","lab":"computing","ex":{"en":"No attachment was included.","cn":"没有附件。"}},{"en":"the act of joining one thing to another; a thing that joins two things together","cn":"连接；连接物","g":"[uncountable, countable]","ex":{"en":"All cars have points for the attachment of safety restraints.","cn":"所有轿车都有安全保护装置的接口。"}},{"en":"a feeling of love for somebody/something","cn":"依恋；爱慕","g":"[countable, uncountable]","ex":{"en":"a child’s strong attachment to its parents","cn":"孩子对父母的强烈依恋"}},{"en":"belief in and support for an idea or a set of values","cn":"信念；信仰；忠诚；拥护","g":"[countable, uncountable]","ex":{"en":"the popular attachment to democratic government","cn":"对民主政府的普遍拥护"}},{"en":"a tool that you can fix onto a machine, to make it do another job","cn":"（机器的）附件，附加装置，附属物","g":"[countable]","ex":{"en":"an electric drill with a range of different attachments","cn":"配有各种附件的电钻"}},{"en":"a short time spent working with an organization such as a hospital, school or part of the armed forces","cn":"暂时隶属于（某医院、学校、部队等）；短期在…工作","g":"[countable, uncountable]","lab":"British English","ex":{"en":"a 4-month training attachment","cn":"为期 4 个月的培训"}}]}},"attic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"顶楼；阁楼","en":"An attic is a room at the top of a house just below the roof."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a space or room just below the roof of a house, often used for storing things 〔","cn":"常用于储物的〕阁楼﹐顶楼"}]},"collocations":{"phrases":["ADJ. cramped, little, small, tiny | converted Her photography studio was a converted attic. | dark, dusty","ATTIC + NOUN bedroom, flat, room | stairs, steps | skylight, window"]},"media":{"uk":"media/ldoce/hwd/bre/e/attic0205.mp3","us":"media/ldoce/hwd/ame/3/attic.mp3"},"examples":[{"en":"furniture stored in the attic","cn":"存放在阁楼的家具"},{"en":"an attic bedroom","cn":"顶楼卧室"}],"oxford":{"phon":"ˈætɪk","pos":"noun","senses":[{"en":"a room or space just below the roof of a house, often used for storing things","cn":"（紧靠屋顶的）阁楼，顶楼","ex":{"en":"furniture stored in the attic","cn":"存放在阁楼的家具"}}]}},"atom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"原子","en":"An atom is the smallest amount of a substance that can take part in a chemical reaction.","ex":{"en":"A methane molecule is composed of one carbon atom attached to four hydrogens.","cn":"甲烷分子由1个碳原子与4个氢原子构成。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the smallest part of an element that can exist alone or can combine with other substances to form a molecule","cn":"原子"},{"en":"a very small amount of something – used for emphasis","cn":"一点儿〔用于强调〕"}]},"vocab":{"pos":"n","senses":[{"en":"An atom is the basic unit of an element. When you see the chemical formula for water, H2O, it's telling you that each molecule of water is made up of two atoms of hydrogen and one atom of oxygen."}]},"collocations":{"phrases":["ADJ. charged, unstable positively charged atoms | carbon, nitrogen, etc.","VERB + ATOM split The scientist Ernest Rutherford was the first person to split the atom.","ATOM + NOUN bomb"]},"media":{"uk":"media/ldoce/hwd/bre/d/atom0205.mp3","us":"media/ldoce/hwd/ame/6/atom.mp3"},"examples":[{"en":"Two atoms of hydrogen combine with one atom of oxygen to form a molecule of water.","cn":"两个氢原子和一个氧原子结合组成一个水分子。"},{"en":"the splitting of the atom","cn":"原子的分裂"}],"oxford":{"phon":"ˈætəm","pos":"noun","senses":[{"en":"the smallest particle of a chemical element that can exist","cn":"原子","ex":{"en":"the splitting of the atom","cn":"原子的分裂"}}]}}});
